import { test, expect } from '@playwright/test';

test.describe('404 Page Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display 404 page when accessing invalid URL', async ({ page }) => {
    // Navigate to an invalid URL
    await page.goto('/invalid-page');

    // Verify 404 error message is visible
    const errorMessage = page.getByText('Page not found');
    await expect(errorMessage).toBeVisible();

    // Verify navigation back button is present
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();

    // Verify page title is set to 404
    const pageTitle = page.getByText('404 - Page not found');
    await expect(pageTitle).toBeVisible();

    // Verify navigation back button works
    await backButton.click();
    await expect(page.url()).toContain('/');
  });

  test('should handle edge case: empty URL', async ({ page }) => {
    // Navigate to an empty URL
    await page.goto('/');

    // Verify 404 page is displayed
    const errorMessage = page.getByText('Page not found');
    await expect(errorMessage).toBeVisible();

    // Verify navigation back button is present
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();

    // Verify page title is set to 404
    const pageTitle = page.getByText('404 - Page not found');
    await expect(pageTitle).toBeVisible();

    // Verify navigation back button works
    await backButton.click();
    await expect(page.url()).toContain('/');
  });
});
